 "content": "from collections import deque


def transform(grid):
    """Mark a 3x3 neighborhood around each 2 embedded in a 3-panel."""
    h, w = len(grid), len(grid[0])
    seen = set()
    panel_boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            panel_boxes.append((min(y for y, _ in cells), max(y for y, _ in cells),
                                min(x for _, x in cells), max(x for _, x in cells)))

    out = [row[:] for row in grid]
    centers = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if any(r0 <= r <= r1 and c0 <= c <= c1
                   for r0, r1, c0, c1 in panel_boxes):
                centers.add((r, c))
    for r, c in centers:
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                if (y, x) != (r, c) and grid[y][x] != 2:
                    out[y][x] = 1
    return out
